package com.payslipmax.pdfparser.guide.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * The Part II lookup, generated by `docs/Plan/rule_cards/tools/part2_nav.py` and `part2_casualty.py` from the files in `part2/`: the 303
 * ODP-2026 Annexure II code pages and the ribbon layout that homes each of them once. Plain strings, ints and lists only, so the
 * release build needs no keep rule (`scripts/check_r8_guide.py` proves it). Names are the manual's own wording, content and not UI
 * copy. [version] is this section's own and is independent of the bundle's.
 */
@Serializable
data class Part2Lookup(
    val version: Int,
    val limits: Part2LookupLimits,
    /** Group letter (`A`, `AM`, `B`, `C`, `CM`) to what it means, from para 3 of the manual. */
    val groups: Map<String, String>,
    val serials: List<Part2CodePage>,
    /** In build order; the Records ribbon, which is lookup by design, is last. */
    val ribbons: List<Part2Ribbon>,
    /** Annexure III: what each serial's From, To and Data 1-4 columns need (`Part2CasualtyModels.kt`). Empty in a bundle built before them. */
    val columns: List<Part2ColumnRow> = emptyList(),
    /** The plain-English pages for about 30 casualties; empty in a bundle that carries none. */
    val about: List<Part2AboutPage> = emptyList(),
    /** "Usually published with" links; empty in a bundle that carries none. */
    val related: List<Part2RelatedRow> = emptyList(),
)

/** The limits `part2_codes_check.py` and `part2_nav.py` enforced and the validator rechecks: their one home, so Kotlin holds no second copy. */
@Serializable
data class Part2LookupLimits(
    val text: Int,
    @SerialName("title_words") val titleWords: Int,
    @SerialName("ribbons_min") val ribbonsMin: Int,
    @SerialName("ribbons_max") val ribbonsMax: Int,
    @SerialName("cases_per_ribbon") val casesPerRibbon: Int,
    @SerialName("case_serials_min") val caseSerialsMin: Int,
    @SerialName("case_serials_max") val caseSerialsMax: Int,
    /** Longest column caption and longest plain-English part, in characters; zero in a bundle that carries neither. */
    val caption: Int = 0,
    @SerialName("about_part") val aboutPart: Int = 0,
)

/**
 * One Annexure II serial (for example `5.1`): its HRMS [codes] (more than one for the eight variant serials), the manual's [name], and
 * the printed [page] of its Annexure III row. [group] is null only where the manual prints none (3.28 and 11.8): none is ever inferred.
 */
@Serializable
data class Part2CodePage(
    val serial: String,
    val chapter: Int,
    val codes: List<String>,
    val group: String? = null,
    val name: String,
    val page: Int,
)

/** A ribbon of cases. Tiles show only for a [built] ribbon, which is one whose drafts ship (the lookup-only Records ribbon is built too). */
@Serializable
data class Part2Ribbon(
    val id: String,
    val title: String,
    val built: Boolean = false,
    val cases: List<Part2Case>,
)

/** A case tile. [serials] are homed here, [also] are homed elsewhere, and [lookup] are the homed serials the officer only looks up. */
@Serializable
data class Part2Case(
    val id: String,
    val title: String,
    val serials: List<String>,
    val also: List<String> = emptyList(),
    val lookup: List<String> = emptyList(),
)
